"""Reviewed counter-app fixture for the build recipes; not generated by an AI model."""

# ruff: noqa: E501
from dsgpt.app_builder import project_files


def fixture(project_id):
    files = {
        **project_files("android", "Counter Check", project_id),
        **project_files("windows", "Counter Check", project_id),
    }
    activity = next(p for p in files if p.endswith("MainActivity.kt"))
    package = files[activity].splitlines()[0].removeprefix("package ")
    folder = activity.rsplit("/", 1)[0]
    files[folder + "/Counter.kt"] = f"""package {package}
object Counter {{
    fun increment(value: Int): Int = if (value < 100) value + 1 else 100
    fun reset(): Int = 0
}}
"""
    files[activity] = f"""package {package}
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
class MainActivity : ComponentActivity() {{
    override fun onCreate(state: Bundle?) {{
        super.onCreate(state)
        val preferences = getSharedPreferences("counter", MODE_PRIVATE)
        setContent {{
            var count by remember {{ mutableIntStateOf(preferences.getInt("count", 0)) }}
            MaterialTheme {{
                Column(Modifier.fillMaxSize().imePadding().padding(24.dp)) {{
                    Text("Count: $count")
                    Button(onClick = {{ count = Counter.increment(count)
                        preferences.edit().putInt("count", count).apply() }}) {{ Text("Add one") }}
                    Button(onClick = {{ count = Counter.reset()
                        preferences.edit().putInt("count", count).apply() }}) {{ Text("Reset") }}
                }}
            }}
        }}
    }}
}}
"""
    files["android/app/src/test/java/CounterTest.kt"] = f"""import {package}.Counter
import org.junit.Test
import org.junit.Assert.assertEquals
class CounterTest {{
    @Test fun incrementsAndCaps() {{ assertEquals(1, Counter.increment(0)); assertEquals(100, Counter.increment(100)) }}
    @Test fun resets() {{ assertEquals(0, Counter.reset()) }}
}}
"""
    files["windows/counter.h"] = (
        "#pragma once\ninline int increment(int n) { return n < 100 ? n + 1 : 100; }\n"
    )
    files["windows/tests.cpp"] = """#include "counter.h"
#include <cassert>
int main() { assert(increment(0)==1); assert(increment(99)==100); assert(increment(100)==100); }
"""
    files["windows/main.cpp"] = (
        files["windows/main.cpp"]
        .replace(
            "#include <windows.h>",
            """#include <windows.h>
#include "counter.h"
#include <string>
int count = 0;
HWND label = nullptr;
""",
        )
        .replace(
            "    if (message == WM_DESTROY)",
            """    if (message == WM_CREATE) {
        label = CreateWindowW(L"STATIC", L"Count: 0", WS_CHILD|WS_VISIBLE, 20,20,200,30,window,nullptr,nullptr,nullptr);
        CreateWindowW(L"BUTTON",L"Add one",WS_CHILD|WS_VISIBLE,20,60,120,40,window,(HMENU)1,nullptr,nullptr);
        CreateWindowW(L"BUTTON",L"Reset",WS_CHILD|WS_VISIBLE,160,60,120,40,window,(HMENU)2,nullptr,nullptr);
        return 0;
    }
    if (message == WM_COMMAND) {
        count = LOWORD(wparam)==1 ? increment(count) : 0;
        SetWindowTextW(label,(L"Count: "+std::to_wstring(count)).c_str());
        return 0;
    }
    if (message == WM_DESTROY)""",
        )
    )
    return files
